#[test]
fn exec_group_replaces_leader_and_clears_only_same_tgid_threads() {
    let mut table: ProcessTable<8> = ProcessTable::new();
    let init = table.create_init(Credentials::root()).unwrap();
    let leader = table.fork(init).unwrap();
    // a second independent task must survive the group exec
    let bystander = table.fork(init).unwrap();
    let before_b = table.view(bystander).unwrap();
    let (id, epoch) = table.exec_group(leader).unwrap();
    assert_eq!(id.pid, leader.pid);
    assert!(epoch >= 1);
    let after = table.view(id).unwrap();
    assert_eq!(after.state, TaskState::Running);
    assert_eq!(after.exec_epoch, epoch);
    // bystander untouched: still present with same identity
    let after_b = table.view(bystander).unwrap();
    assert_eq!(after_b.id.pid, before_b.id.pid);
    assert_eq!(after_b.tgid, before_b.tgid);
}

#[test]
fn identity_hostname_read_and_pid_uts_namespace_links_are_exact() {
    let (tasks, count) = fixture();
    let identity = IdentityView {
        hostname: b"instance-a",
        machine_id: b"0123456789abcdef0123456789abcdef",
        boot_id: b"11111111-2222-3333-4444-555555555555",
    };
    let identities = IdentityFs::new(
        &tasks[..count],
        identity,
        NamespaceView { mount: 101, pid: 102, uts: 103, cgroup: 104 },
    );
    let mut output = [0u8; 128];
    let len = identities.read(b"/etc/hostname", &mut output).unwrap();
    assert_eq!(&output[..len], b"instance-a\n");
    let len = identities.readlink(b"/proc/1/ns/pid", &mut output).unwrap();
    assert_eq!(&output[..len], b"pid:[102]");
    let len = identities.readlink(b"/proc/1/ns/uts", &mut output).unwrap();
    assert_eq!(&output[..len], b"uts:[103]");
    // unknown namespace leaf still NotFound
    assert_eq!(
        identities.readlink(b"/proc/1/ns/net", &mut output),
        Err(ViewError::NotFound)
    );
}

#[test]
fn safe_whiteout_dir_rejects_non_normal_components_and_missing_leaf_is_ok() {
    let root = temp_dir("whiteout-components");
    // parent with a CurDir component is rejected (non-Normal)
    assert!(safe_whiteout_dir(&root, Path::new("./sub")).is_err());
    // parent with ParentDir is rejected
    assert!(safe_whiteout_dir(&root, Path::new("../escape")).is_err());
    // absolute prefix is rejected
    assert!(safe_whiteout_dir(&root, Path::new("/abs")).is_err());
    // plain missing directories are tolerated (created later by the layer)
    let ok = safe_whiteout_dir(&root, Path::new("fresh/deeper")).unwrap();
    assert_eq!(ok, root.join("fresh/deeper"));
    // empty parent resolves to the root itself
    assert_eq!(safe_whiteout_dir(&root, Path::new("")).unwrap(), root);
    fs::remove_dir_all(root).unwrap();
}

#[test]
fn parse_section_rejects_malformed_headers_and_accepts_minimal() {
    // minimal-length header of an unknown section: shape passes, section unknown
    assert_eq!(parse_section(b"[a]"), Err(ConfigError::UnknownSection));
    // too short
    assert_eq!(parse_section(b"[]"), Err(ConfigError::InvalidSyntax));
    // missing closing bracket
    assert_eq!(parse_section(b"[audit"), Err(ConfigError::InvalidSyntax));
    // nested opening bracket inside the name
    assert_eq!(parse_section(b"[a[b]"), Err(ConfigError::InvalidSyntax));
    // known sections still resolve
    assert_eq!(parse_section(b"[audit]"), Ok(Section::Audit));
}

#[test]
fn shell_code_pins_128_plus_signal_and_exit_passthrough() {
    // exited children pass their code through unchanged
    assert_eq!(ChildStatus::Exited(0).shell_code(), 0);
    assert_eq!(ChildStatus::Exited(7).shell_code(), 7);
    assert_eq!(ChildStatus::Exited(255).shell_code(), 255);
    // signaled children report the shell convention 128 + signal
    assert_eq!(ChildStatus::Signaled(1).shell_code(), 129);
    assert_eq!(ChildStatus::Signaled(9).shell_code(), 137);
    assert_eq!(ChildStatus::Signaled(15).shell_code(), 143);
    assert_eq!(ChildStatus::Signaled(64).shell_code(), 192);
}

